// The pairing layer.
//
// This is the file that makes "learn any Indian language from any language"
// tractable. Nobody authors a Tamil-for-Russian-speakers course. Instead:
//
//   target side  -> COURSES[target].lexicon[conceptId]     (authored once)
//   source side  -> a gloss for the same conceptId          (authored once)
//   the course   -> generated by joining them on conceptId
//
// The source gloss comes from one of two places:
//   * a world language  -> CONCEPTS[].gloss[code]
//   * another INDIAN language -> that language's own course pack
//
// The second case is free. Because both packs are keyed by the same concept
// ids, a Tamil speaker learning Hindi is just a different join, with no new
// content at all. Ten targets x (10 world + 9 Indian) = 190 course pairs from
// twenty authored files.

import { CONCEPTS, CONCEPT_BY_ID, SOURCE_LANGS, UNITS } from '../data/concepts.js'
import { COURSES } from '../data/courses/index.js'
import { TARGETS, TARGET_BY_CODE } from '../data/targets.js'

/** Every language a learner can study FROM. */
export function sourceOptions() {
  return [
    ...SOURCE_LANGS.map((l) => ({ ...l, kind: 'world' })),
    ...TARGETS.map((t) => ({
      code: t.code,
      name: t.name,
      native: t.native,
      dir: t.dir || 'ltr',
      kind: 'indian',
      script: t.script,
      font: t.font,
    })),
  ]
}

const WORLD_CODES = new Set(SOURCE_LANGS.map((l) => l.code))

export const isWorldSource = (code) => WORLD_CODES.has(code)

/** Human-readable name for a source language code, for UI copy. */
export function sourceName(code) {
  const world = SOURCE_LANGS.find((l) => l.code === code)
  if (world) return world.name
  const indian = TARGET_BY_CODE[code]
  return indian ? indian.name : code
}

/**
 * Render one concept in the learner's own language.
 * Returns { text, latn, script } where latn/script are only set when the
 * source language is itself an Indian language written in its own script.
 */
export function glossFor(conceptId, sourceCode) {
  const concept = CONCEPT_BY_ID[conceptId]
  if (!concept) return null

  if (isWorldSource(sourceCode)) {
    return { text: concept.gloss[sourceCode] || concept.gloss.en, latn: null, script: null, pivot: !concept.gloss[sourceCode] }
  }

  const pack = COURSES[sourceCode]
  const entry = pack && pack.lexicon[conceptId]
  if (entry) {
    return {
      text: entry.target,
      latn: entry.latn,
      script: TARGET_BY_CODE[sourceCode].script,
      pivot: false,
    }
  }
  // An Indian source language with a gap falls back to English rather than
  // showing nothing. The coverage report counts these.
  return { text: concept.gloss.en, latn: null, script: null, pivot: true }
}

/** Which source languages are legal for a given target (not the target itself). */
export function validSourcesFor(targetCode) {
  return sourceOptions().filter((s) => s.code !== targetCode)
}

/**
 * Build the full joined course for one (target, source) pair.
 * Everything downstream - lessons, script drills, stats - reads this shape.
 */
export function buildCourse(targetCode, sourceCode) {
  const target = TARGET_BY_CODE[targetCode]
  const pack = COURSES[targetCode]
  if (!target || !pack) throw new Error(`no course pack for target "${targetCode}"`)

  const items = CONCEPTS.filter((c) => pack.lexicon[c.id]).map((c) => {
    const entry = pack.lexicon[c.id]
    return {
      id: c.id,
      unit: c.unit,
      icon: c.icon,
      target: entry.target,
      latn: entry.latn,
      gender: entry.g || null,
      note: entry.note || null,
      gloss: glossFor(c.id, sourceCode),
    }
  })

  const byUnit = Object.fromEntries(UNITS.map((u) => [u.id, []]))
  for (const it of items) byUnit[it.unit].push(it)

  const sentences = pack.sentences.map((sent) => ({
    ...sent,
    // Word-by-word gloss in the learner's language, derived from the token
    // alignment. This is why no sentence needs translating per source language.
    wordGloss: sent.align.map((cid) => (cid ? glossFor(cid, sourceCode) : null)),
  }))

  const units = UNITS.map((u) => ({
    ...u,
    items: byUnit[u.id],
    sentences: sentences.filter((s) => s.unit === u.id),
    grammar: pack.grammar.filter((g) => g.unit === u.id),
  })).filter((u) => u.items.length > 0)

  return {
    target,
    sourceCode,
    review: pack.review,
    register: pack.register || null,
    dir: target.dir || 'ltr',
    units,
    items,
    sentences,
    grammar: pack.grammar,
  }
}

/**
 * How complete is the source-language layer? Used by the coverage report and
 * shown in the UI, because a learner deserves to know when they are being
 * served an English pivot rather than their own language.
 */
export function coverageFor(sourceCode) {
  let have = 0
  for (const c of CONCEPTS) {
    const g = glossFor(c.id, sourceCode)
    if (g && !g.pivot) have += 1
  }
  return { have, total: CONCEPTS.length, pct: Math.round((have / CONCEPTS.length) * 100) }
}
